/// The error every fallible call returns; Dart receives it as an exception.
class ApiError implements FrbException {
  /// What kind of failure this is.
  final ErrorKind kind;

  /// The ARB key of the message the UI shows, such as `"errorInternal"`.
  final String messageKey;

  /// Technical details for "Copy technical details": structural facts only.
  final String? details;

  /// Whether the UI offers Save as: a save that failed for a reason another file avoids.
  final bool offerSaveAs;

  /// On a failed save: no recovery copy of the unsaved edits exists either.
  final bool noRecoveryCopy;

  const ApiError({
    required this.kind,
    required this.messageKey,
    this.details,
    required this.offerSaveAs,
    required this.noRecoveryCopy,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      messageKey.hashCode ^
      details.hashCode ^
      offerSaveAs.hashCode ^
      noRecoveryCopy.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ApiError &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          messageKey == other.messageKey &&
          details == other.details &&
          offerSaveAs == other.offerSaveAs &&
          noRecoveryCopy == other.noRecoveryCopy;
}

/// The version of the API between the engine and the UI.
class ApiVersion {
  /// Incremented on a breaking change.
  final int major;

  /// Incremented on a compatible addition.
  final int minor;

  const ApiVersion({required this.major, required this.minor});

  @override
  int get hashCode => major.hashCode ^ minor.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ApiVersion &&
          runtimeType == other.runtimeType &&
          major == other.major &&
          minor == other.minor;
}

