  /// One page's matches (`Matches`).
  final List<SearchMatch> matches;

  /// Pages read (`Progress`).
  final int searched;

  /// Pages in the document (`Progress`).
  final int pages;

  /// Whether it was cancelled (`Done`).
  final bool cancelled;

  /// Whether no page had text, a scan (`Done`).
  final bool textless;

  const SearchEvent({
    required this.kind,
    required this.search,
    required this.matches,
    required this.searched,
    required this.pages,
    required this.cancelled,
    required this.textless,
  });

  @override
  int get hashCode =>
      kind.hashCode ^
      search.hashCode ^
      matches.hashCode ^
      searched.hashCode ^
      pages.hashCode ^
      cancelled.hashCode ^
      textless.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchEvent &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          search == other.search &&
          matches == other.matches &&
          searched == other.searched &&
          pages == other.pages &&
          cancelled == other.cancelled &&
          textless == other.textless;
}

/// What a search event says.
enum SearchEventKind {
  /// The search runs: `search` is its handle. The first event.
  started,

  /// One page's `matches`.
  matches,

  /// `searched` of `pages` pages read.
  progress,

  /// It ended; `cancelled` says how. The last event.
  done,
}

