  final int y;

  /// The bitmap's width in pixels.
  final int width;

  /// The bitmap's height in pixels.
  final int height;

  /// Bytes per row.
  final int stride;

  /// 8-bit BGRA, opaque; it reaches Dart without a copy (the Dco codec).
  final Uint8List pixels;

