      kind.hashCode ^
      page.hashCode ^
      zoomBucket.hashCode ^
      devicePixelRatio.hashCode ^
      column.hashCode ^
      row.hashCode ^
      size.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ViewItem &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          page == other.page &&
          zoomBucket == other.zoomBucket &&
          devicePixelRatio == other.devicePixelRatio &&
          column == other.column &&
          row == other.row &&
          size == other.size;
}

